import React, { useState, useEffect } from 'react'; // 1. Thêm useEffect
import chatBgImg from '../../assets/nen_khung_chat.jpg'; 

const NhanTin = () => {
    const [tabActive, setTabActive] = useState('all');
    const [selectedRooms, setSelectedRooms] = useState([]);
    const [message, setMessage] = useState('');

    // 2. Khởi tạo state từ localStorage nếu có, nếu không thì để mảng trống
    const [chatHistory, setChatHistory] = useState(() => {
        const savedChat = localStorage.getItem('chatHistory');
        return savedChat ? JSON.parse(savedChat) : [];
    });

    // 3. Sử dụng useEffect để tự động lưu chatHistory mỗi khi nó thay đổi
    useEffect(() => {
        localStorage.setItem('chatHistory', JSON.stringify(chatHistory));
    }, [chatHistory]);

    const allRooms = [];
    for (let floor = 1; floor <= 9; floor++) {
        for (let num = 1; num <= 5; num++) {
            allRooms.push(`${floor}0${num}`);
        }
    }

    const toggleRoom = (roomId) => {
        if (selectedRooms.includes(roomId)) {
            setSelectedRooms(selectedRooms.filter(id => id !== roomId));
        } else {
            setSelectedRooms([...selectedRooms, roomId]);
        }
    };

    const handleSendMessage = (type) => {
        if (message.trim() === '') return;

        const newMessage = {
            id: Date.now(),
            sender: "AD",
            content: message,
            type: type, 
            target: type === 'all' ? 'Tất cả' : selectedRooms.join(', '),
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        };

        setChatHistory([...chatHistory, newMessage]);
        setMessage('');
    };

    const canSendPrivate = selectedRooms.length > 0 && message.trim() !== '';

    return (
        <div style={{
            flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', 
            backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover',
            backgroundPosition: 'center', overflow: 'hidden'
        }} className="glass-card">

            <div style={{ padding: '20px', display: 'flex', gap: '15px' }}>
                <button 
                    onClick={() => setTabActive('all')}
                    style={{
                        padding: '10px 25px', borderRadius: '20px', border: 'none', fontWeight: 'bold',
                        backgroundColor: tabActive === 'all' ? '#333' : 'rgba(255,255,255,0.6)',
                        color: tabActive === 'all' ? '#fff' : '#333', cursor: 'pointer'
                    }}
                >
                    Nhắn tin chung
                </button>
                <button 
                    onClick={() => setTabActive('private')}
                    style={{
                        padding: '10px 25px', borderRadius: '20px', border: 'none', fontWeight: 'bold',
                        backgroundColor: tabActive === 'private' ? '#8b5e5e' : 'rgba(255,255,255,0.6)',
                        color: tabActive === 'private' ? '#fff' : '#333', cursor: 'pointer'
                    }}
                >
                    Nhắn tin riêng
                </button>
            </div>

            <div style={{ flex: 1, padding: '0 20px 20px 20px', display: 'flex', overflow: 'hidden' }}>
                {tabActive === 'all' ? (
                    <div style={{ flex: 1, display: 'flex', flexDirection: 'column' }}>
                        <div style={{ flex: 1, padding: '10px', overflowY: 'auto' }}>
                            {chatHistory.filter(m => m.type === 'all').map(msg => (
                                <div key={msg.id} style={{ display: 'flex', gap: '10px', alignItems: 'flex-start', marginBottom: '15px' }}>
                                    <div style={{ 
                                        minWidth: '35px', height: '35px', borderRadius: '50%', 
                                        backgroundColor: '#333', color: '#fff', display: 'flex', 
                                        alignItems: 'center', justifyContent: 'center', fontSize: '10px', fontWeight: 'bold' 
                                    }}>
                                        {msg.sender}
                                    </div>
                                    <div style={{ backgroundColor: 'rgba(255,255,255,0.9)', padding: '12px 18px', borderRadius: '18px 18px 18px 0', fontSize: '13px', color: '#333', maxWidth: '70%' }}>
                                        {msg.content}
                                        <div style={{ fontSize: '9px', opacity: 0.5, marginTop: '5px', textAlign: 'right' }}>{msg.time}</div>
                                    </div>
                                </div>
                            ))}
                        </div>
                        <div style={{ display: 'flex', gap: '10px' }}>
                            <input 
                                style={{ flex: 1, padding: '15px', borderRadius: '15px', border: 'none', outline: 'none' }} 
                                placeholder="Gửi tin nhắn đến toàn thể cư dân..." 
                                value={message}
                                onChange={(e) => setMessage(e.target.value)}
                            />
                            <button 
                                onClick={() => handleSendMessage('all')}
                                style={{ padding: '0 30px', borderRadius: '15px', border: 'none', backgroundColor: '#333', color: '#fff', fontWeight: 'bold', cursor: 'pointer' }}
                            >
                                Gửi
                            </button>
                        </div>
                    </div>
                ) : (
                    <div style={{ flex: 1, display: 'flex', gap: '20px' }}>
                        <div style={{ 
                            width: '230px', display: 'grid', gridTemplateColumns: 'repeat(5, 1fr)', 
                            gap: '6px', alignContent: 'flex-start', overflowY: 'auto', paddingRight: '5px'
                        }}>
                            {allRooms.map(room => {
                                const isSelected = selectedRooms.includes(room);
                                return (
                                    <div 
                                        key={room} 
                                        onClick={() => toggleRoom(room)}
                                        style={{ 
                                            background: isSelected ? '#8b5e5e' : 'white', 
                                            color: isSelected ? 'white' : '#333',
                                            padding: '8px 0', borderRadius: '8px', textAlign: 'center', 
                                            fontSize: '11px', fontWeight: 'bold', cursor: 'pointer',
                                            border: isSelected ? 'none' : '1px solid #ddd'
                                        }}
                                    >
                                        {room}
                                    </div>
                                );
                            })}
                        </div>

                        <div style={{ 
                            flex: 1, display: 'flex', flexDirection: 'column', 
                            backgroundColor: 'rgba(255,255,255,0.1)', borderRadius: '20px', 
                            border: '1px solid rgba(255,255,255,0.2)', padding: '15px'
                        }}>
                            <div style={{ flex: 1, color: '#fff', overflowY: 'auto' }}>
                                <p style={{ fontSize: '14px', fontWeight: 'bold', marginBottom: '10px' }}>
                                    Gửi đến: {selectedRooms.length > 0 ? selectedRooms.join(', ') : 'Chưa chọn phòng'}
                                </p>

                                {chatHistory.filter(m => m.type === 'private').map(msg => (
                                    <div key={msg.id} style={{ display: 'flex', gap: '10px', marginBottom: '15px', justifyContent: 'flex-end' }}>
                                        <div style={{ backgroundColor: '#8b5e5e', padding: '10px 15px', borderRadius: '15px 15px 0 15px', fontSize: '12px', maxWidth: '80%' }}>
                                            <div style={{ fontSize: '10px', fontWeight: 'bold', borderBottom: '1px solid rgba(255,255,255,0.2)', marginBottom: '5px', paddingBottom: '2px' }}>
                                                Tới: {msg.target}
                                            </div>
                                            {msg.content}
                                        </div>
                                    </div>
                                ))}
                            </div>

                            <div style={{ display: 'flex', gap: '10px', marginTop: '10px' }}>
                                <input 
                                    style={{ flex: 1, padding: '15px', borderRadius: '15px', border: 'none', outline: 'none' }} 
                                    placeholder="Nhập nội dung nhắn riêng..." 
                                    value={message}
                                    onChange={(e) => setMessage(e.target.value)}
                                />
                                <button 
                                    disabled={!canSendPrivate}
                                    onClick={() => handleSendMessage('private')}
                                    style={{ 
                                        padding: '0 25px', borderRadius: '15px', border: 'none', 
                                        backgroundColor: '#8b5e5e', color: '#fff', fontWeight: 'bold',
                                        opacity: canSendPrivate ? 1 : 0.5,
                                        cursor: canSendPrivate ? 'pointer' : 'not-allowed'
                                    }}
                                >
                                    Gửi riêng
                                </button>
                            </div>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

export default NhanTin;
